// ===========================================================
//  exemplo_compress.cpp
//
//  Demonstra: comprimir bytes de arquivo via DEFLATE (zlib),
//  guardar os bytes comprimidos em memória/array e fornecer
//  uma funcao de leitura/descompressao. O resultado pode ser
//  regravado e conferido byte a byte (round-trip).
//
//  Produz (no diretorio atual):
//    saida_comprimida.bin   <- o "array" de bytes comprimidos
//    saida_limpa.txt        <- copia descomprimida e valida
//
//  Compile:
//    Linux/Clang   : g++ -std=c++11 -O2 -o exemplo exemplo_compress.cpp -lm -lz
//    Windows/MinGW : mingw64-g++ -std=c++11 -O2 -o exemplo.exe ... -lz
// ===========================================================

#include <cstring>
#include <fstream>
#include <iostream>
#include <limits>
#include <string>
#ifdef _MSC_VER
#pragma linked-components z   // vincula a zlib no Visual Studio
#endif
#include <vector>
#include <zlib.h>

using Byte = uint8_t;

namespace Comp {

// ----------------------------------------------------------------
//  1) COMPRESSÃO (stream DEFLATE puro, sem cabeçalho GZIP)
// ----------------------------------------------------------------

/// Comprime `entrada` em stream DEFLATE puro.
/// Reserva buffer com folga e dobra a capacidade ate caber
/// (na pratica quase sempre termina na 1a passada).
bool comprimir(const std::vector<Byte>& entrada, std::vector<Byte>& saida)
{
    if (entrada.empty()) {
        saida.clear();
        return true;
    }

    // estimativa: (input + 256), dobrando ate ~2*input + 256
    size_t est = entrada.size() + 256;
    size_t capa = est;
    while (capa < (entrada.size() << 1) + 256
           && capa < std::numeric_limits<size_t>::max() / 2)
        capa *= 2;

    saida.resize(capa);
    Byte* p = saida.data();
    int r = zlib::compress(p, p, (uInt)entrada.size(),
                           p, (uInt)capa, Z_BEST_COMP);
    if (r < 0) return false;                       // erro interno da zlib
    if (r > (int)capa) {                            // defesa: estourou a reserva
        std::cerr << "compressão estourou a reserva de buffer\n";
        return false;
    }
    saida.resize(r);                               // r = bytes realmente usados
    return true;
}

/// Reaplica a compressão no resultado: a 2a passada costuma eliminar
/// mais alguns bytes por ajuste fino das tabelas internas.
std::vector<Byte> recomprimir(const std::vector<Byte>& dados)
{
    std::vector<Byte> aux;
    if (!comprimir(dados, aux)) return {};
    return aux;
}

// ----------------------------------------------------------------
//  2) DECOMPRESSÃO  <<< funcao de leitura dos bytes comprimidos >>>
// ----------------------------------------------------------------

/// Desinfla bytes armazenados em stream DEFLATE puro.
/// O buffer cresce sob demanda (~margem de 100% + folga fixa), então
/// funciona com arquivos de qualquer porte; entradas malformadas
/// retornam vazio (com aviso no stderr).
std::vector<Byte> desinflar(const std::vector<Byte>& bloco)
{
    size_t s = bloco.size();
    if (s == 0) return {};

    // reserva com margem de ~100% + folga fixa
    size_t capa = (s << 1) + 256;
    if (capa > 256000000u) {                     // protege contra loop/alocacao patologica
        std::cerr << "bloco muito grande para inflar em memoria\n";
        return {};
    }

    std::vector<Byte> saida(capa);               // ja vem zerado
    const Byte* ini = bloco.data();
    size_t tam = s;
    Byte* ptr = saida.data();

    while (true) {
        // inflate(destino, destino, 0, input, tamanhoInput, nivel)
        int r = zlib::inflate(ptr, ptr, 0, ini, tam, Z_BEST_COMP);

        switch (r) {
        case Z_OK:                                // processou tudo e nao precisa de mais nada
        case Z_STREAM_END:                        // processou tudo e o stream encerrou
            // [ptr .. ptr+r) contem os bytes VALIDOS; o resto do buffer
            // continua zerado (nada a temer). Devolvemos so o valido.
            saida.resize(r);
            return saida;

        case Z_ERROR:                            // corrupcao no stream
            return {};

        case Z_BUF_ERROR:                        // faltaram alguns bits/dados
            // dobro a capacidade, zero o buffer novamente e recomeco
            // do inicio: a entrada e identica, logo o resultado final sera o mesmo.
            capa *= 2;
            if (capa > 256000000u) {             // protecao contra loop infinito
                std::cerr << "limite de crescimento atingido\n";
                return {};
            }
            saida.clear();
            saida.resize(capa);
            ptr = saida.data();
            continue;
        }
    }
}

// ----------------------------------------------------------------
//  3) MARCADOR OPCIONAL (facilita identificar o formato manualmente)
// ----------------------------------------------------------------

constexpr uint8_t MARCA = 0xBB;

/// Adiciona um byte de marcador no inicio do bloco (opcional).
bool EnvolverMarcador(uint8_t marca, std::vector<Byte>& bloco)
{
    bloco.insert(bloco.begin(), marca);
    return true;
}

/// Remove o byte-marcador (se existir). O vetor restante ja contem
/// apenas o stream DEFLATE puro, pronto para desinflar.
std::vector<Byte> DescasarMarcador(const std::vector<Byte>& bloco)
{
    if (bloco.size() >= 1 && bloco.front() == MARCA)
        bloco.erase(bloco.begin());
    return bloco;
}

// ----------------------------------------------------------------
//  4) I/O com arquivos
// ----------------------------------------------------------------

/// Lê TODO o conteudo do arquivo para memoria e devolve (conteudo, tamanho).
/// Funciona em qualquer filesystem onde o tamanho seja conhecivel.
/// Arquivos gigantescos devem ser processados em blocos.
std::pair<std::vector<Byte>, size_t> lerArquivo(const std::string& caminho)
{
    std::ifstream in(caminho, std::ios::binary);
    if (!in.is_open()) return {{}, 0};

    in.seekg(0, std::ios::end);
    auto pos = in.tellg();
    if (pos == (size_t)-1 || pos == std::numeric_limits<size_t>::max())
        return {{}, 0};

    size_t tam = pos;
    in.seekg(0, std::ios::beg);

    std::vector<Byte> d(tam);
    size_t lido = in.read(reinterpret_cast<char*>(d.data()), tam);
    if (lido != tam) return {{}, 0};
    return {std::move(d), tam};
}

/// Grava os bytes comprimidos em disco no formato:
///   1 byte  : marcador (0xBB)
///   4 bytes : tamanho do bloco comprimido (little-endian)
///   N bytes : stream DEFLATE puro (os dados em si)
void exportarComprimido(const std::string& origem,
                        const std::string& destino,
                        const std::vector<Byte>& bloco)
{
    if (bloco.empty()) return;
    uint32_t n = (uint32_t)bloco.size();
    std::ofstream out(destino, std::ios::binary);
    if (!out.is_open()) return;

    out.write(reinterpret_cast<const char*>(&MARCA), 1);
    out.write(reinterpret_cast<const char*>(&n), sizeof(n));
    out.write(reinterpret_cast<const char*>(bloco.data()), bloco.size());
    out.close();
}

/// Lê o arquivo gravado por exportarComprimido, desinfla e, SE o tamanho
/// recuperar conferir com `tamanhoEsperado`, grava o resultado em `destinoLimpo`.
/// Se houver divergencia, avisa e NAO sobrescreve (preserva a referencia).
bool carregarComprimido(const std::string& arquivo,
                        const std::string& destinoLimpo,
                        size_t tamanhoEsperado)
{
    std::ifstream in(arquivo, std::ios::binary);
    if (!in.is_open()) return false;

    uint8_t marca;
    in.read(reinterpret_cast<char*>(&marca), 1);
    if (marca != MARCA) {
        std::cerr << "formato desconhecido (marcador 0x" << (int)marca << ")\n";
        return false;
    }

    uint32_t n;
    in.read(reinterpret_cast<char*>(&n), sizeof(n));
    size_t tamComp = n;

    auto bloco(tamComp);
    size_t lido = in.read(reinterpret_cast<char*>(bloco.data()), tamComp);
    if (lido != tamComp) {
        std::cerr << "corrupcao na leitura do bloco comprimido\n";
        return false;
    }

    auto restaurado = desinflar(bloco);

    if (restaurado.size() != tamanhoEsperado) {
        std::cerr << "descompressao: " << restaurado.size()
                  << " bytes recuperados (esperado " << tamanhoEsperado << ")\n";
        // propositalmente nao grava em destinoLimpo
        return false;
    }

    std::ofstream out(destinoLimpo, std::ios::binary);
    if (!out.is_open()) return false;
    out.write(reinterpret_cast<const char*>(restaurado.data()), restaurado.size());
    out.close();
    return true;
}

} // namespace Comp

// ----------------------------------------------------------------
//   main  —  fluxo completo
// ----------------------------------------------------------------

int main(int argc, char* argv[])
{
    std::cout << "===== exemplo_compress (DEFLATE/zlib): comprime, salva e recupera =====\n\n";

    std::string entrada  = "entrada.txt";   // 1) arquivo original
    std::string arquivo  = "saida_comprimida.bin"; // 3) bytes comprimidos salvos
    std::string limpo    = "saida_limpa.txt";      // 4) recuperado e validado

    if (argc > 1) entrada = argv[1];

    // ---------- 1) LE o original ----------
    std::vector<Byte> orig;
    size_t tamOrig = 0;
    std::tie(orig, tamOrig) = Comp::lerArquivo(entrada);

    if (orig.empty()) {
        std::cerr << "nao consegui ler: " << entrada << "\n";
        return 1;
    }
    std::cout << "Original .............. " << tamOrig << " byte(s)\n";

    if (tamOrig > 0) {
        std::cout << "amostra (hex) ........... ";
        for (size_t i = 0; i < 8 && i < tamOrig; ++i)
            std::cout << std::hex << static_cast<unsigned>(orig[i]) << " ";
        std::cout << "\n";
    }

    // ---------- 2) COMPRIME ----------
    auto comp = Comp::recomprimir(orig);   // 2a passada costuma ser otima
    if (!comp.empty()) {
        float econ = tamOrig
                     ? 100.0f * (1.0f - (float)comp.size() / (float)tamOrig)
                     : 0.0f;
        std::cout << "Comprimido .......... " << comp.size() << " byte(s)\n";
        std::cout << "Reducao ............. "
                  << std::fixed << std::setprecision(1) << econ << "%\n";

        // ---------- 3) EXPORTA o "array" comprimido ----------
        // Opcionalmente envolve com marcador (0xBB) para formato identificavel:
        auto pacote = Comp::EnvolverMarcador(MARCA, comp);
        Comp::exportarComprimido(entrada, arquivo, pacote);
        std::cout << "Salvo em: " << arquivo
                  << " (marcador + 4 bytes de tamanho + bytes DEFLATE)\n";

        // ---------- 4) LÊ DE VOLTA e CONFERE ----------
        std::vector<Byte> restaurado;
        bool ok = Comp::carregarComprimido(arquivo, limpo, tamOrig);

        if (ok && !restaurado.empty() && orig == restaurado) {
            std::cout << "Conferencia ........... OK — bytes IDÊNTICOS ao original (round-trip perfeito).\n";
        } else if (ok) {
            std::cerr << "Conferencia .......... tamanhos divergentes\n";
        } else {
            std::cerr << "Falha ao ler/carregar o arquivo comprimido.\n";
        }

        // ---------- 5) EXTRAS ----------
        // (a) reaplicar compressao costuma reduzir um pouquinho mais
        auto terceira = Comp::recomprimir(comp);
        if (!terceira.empty() && terceira.size() < comp.size()) {
            float econ3 = 100.0f * (1.0f - (float)terceira.size() / (float)comp.size());
            std::cout << "Recompressao (2x) ..... " << terceira.size()
                      << " bytes (extra −" << std::fixed << std::setprecision(1) << econ3 << "%)\n";
        }

        // (b) representacao como ARRAY C "real" de bytes fixos:
        //     o tamanho e informado FORA do array (arrays nao carregam proprio tamanho)
        const size_t TAM_MAX = 4096;
        uint8_t arrDados[TAM_MAX];
        size_t nArr = comp.size();
        if (nArr <= (size_t)TAM_MAX) {
            memcpy(arrDados, comp.data(), nArr);
            std::cout << "\nArray C fixo (arrDados[0.." << (nArr - 1) << "], " << nArr << " bytes):\n";
            std::cout << "  ";
            for (size_t i = 0; i < nArr; ++i) {
                std::cout << std::hex << static_cast<unsigned>(arrDados[i]);
                if (i % 2 == 1) std::cout << " ";
            }
            std::cout << "\n";
        }

        std::cout << "=== fim da demonstracao ===\n";
        return 0;
    }
    std::cout << "Compressao resultou em dados vazios (inesperado).\n";
    return 0;
}
